  var DEFAULT_CUSTOM_TYPE_STRUCTURE = "\u6309\u8BE5\u81EA\u5B9A\u4E49\u7C7B\u578B\u7684\u5199\u4F5C\u573A\u666F\u7EC4\u7EC7\u7ED3\u6784\uFF0C\u4FDD\u6301\u8868\u8FBE\u6E05\u6670\u89C4\u8303";
