    const sourceRequestedCount = Number.parseInt(source.requestedSlideCount || source.slideCount || source.slide_count, 10);
    const requestedCount = autoSlideCount ? Number.isFinite(sourceRequestedCount) ? sourceRequestedCount : rawSlides.length || estimateSlideCountFromContent(fallback.content) : Number.parseInt(fallback.slideCount || source.slideCount || source.slide_count || 12, 10);
    const targetCount = Number.isFinite(requestedCount) ? Math.min(Math.max(requestedCount, 1), 40) : 12;
